with snap as materialized (select pg_catalog.pg_current_snapshot() as __snap, coalesce((select max(seg_seq) from segments), 0) as __seg), a as (select s."grp_hi"::integer as "grp_hi", count(*)::bigint as __rn, (count(*) filter (where (s."score") is not null))::bigint as __rc1, coalesce(sum((s."score")) filter (where scale((s."score")) is not null), 0) as __rs1, (select case when __v.__ka is null then null::jsonb else ( select jsonb_object_agg(__z.__sk, __z.__sc) from ( select __u.__sk::text as __sk, sum(1)::bigint as __sc from unnest(__v.__ka, __v.__wa) as __u(__sk, __sw) where __u.__sk is not null group by __u.__sk having sum(1) <> 0) as __z) end from (select array_agg(coalesce(scale((s."score"))::text, (s."score")::text)) filter (where (s."score") is not null and scale((s."score")) is distinct from 2) as __ka, null::bigint[] as __wa) as __v) as __rk1, (count(*) filter (where (s."likes") is not null))::bigint as __rc2, coalesce(sum((s."likes")::numeric), 0) as __rs2 from "public"."posts" s group by 1), ins as (insert into "trellis"."agg_1" (grp_hi, __n, __count_1, __sum_1, __scales_1, __count_2, __sum_2, __basis, __stamp) select a.grp_hi, a.__rn, a.__rc1, a.__rs1, a.__rk1, a.__rc2, a.__rs2, snap.__snap, snap.__seg from a, snap order by a.grp_hi on conflict (grp_hi) do update set __n = excluded.__n, __count_1 = excluded.__count_1, __sum_1 = excluded.__sum_1, __scales_1 = excluded.__scales_1, __count_2 = excluded.__count_2, __sum_2 = excluded.__sum_2, __basis = excluded.__basis, __stamp = excluded.__stamp returning grp_hi, __n as __nn, __count_1 as __nc1, __sum_1 as __ns1, __scales_1 as __nk1, __count_2 as __nc2, __sum_2 as __ns2) select count(*) from ins;
